"/Users/jamie/.codex/plugins/cache/skillshare-pstack-fe9f343631f3cbe0/pstack/0.9.73/skills/poteto-mode/playbooks/investigation.md",
"/Users/jamie/.codex/plugins/cache/skillshare-pstack-fe9f343631f3cbe0/pstack/0.9.73/skills/unslop/SKILL.md",
"/Users/jamie/.codex/plugins/cache/skillshare-pstack-fe9f343631f3cbe0/pstack/0.9.73/skills/principle-prove-it-works/SKILL.md"
];
text(await tools.exec_command({cmd:"cat " + paths.map(p=>"'"+p+"'").join(" "),max_output_tokens:11000}));
text(await tools.exec_command({cmd:"pwd; command -v exposed; find target -maxdepth 3 -type f -perm +111 -name '*exposed*' 2>/dev/null",max_output_tokens:1000}));

text(await tools.exec_command({cmd:"./target/debug/exposed --help",max_output_tokens:5000}));
text(await tools.exec_command({cmd:"./target/debug/exposed",max_output_tokens:3000}));
text(await tools.exec_command({cmd:"./target/debug/exposed --version",max_output_tokens:1000}));

const args = ["server --help","data --help","migrate --help","search --help"];
const results = await Promise.allSettled(args.map(arg=>tools.exec_command({cmd:"./target/debug/exposed "+arg,max_output_tokens:5000})));
results.forEach((r,i)=>text({command:args[i],result:r}));

const args = ["data latest --help","data copy-latest-raw --help","data declarations --help","data members --help","migrate run --help","data latest"];
const results=await Promise.allSettled(args.map(arg=>tools.exec_command({cmd:"./target/debug/exposed "+arg,max_output_tokens:5500})));
results.forEach((r,i)=>text({command:args[i],result:r}));

