      "description": "Supported acquisition stage for declarations.",
      "oneOf": [
        {
          "description": "Capture source evidence for later offline processing.",
          "type": "string",
          "const": "fetch"
        },
        {
          "description": "Split captured funding occurrences and funder observations offline.",
          "type": "string",
          "const": "clean"
