    /// Equal timestamps use the greatest UUID. An absent or empty store returns `None`.
    /// This operation does not create or change files.
    ///
    /// # Errors
    /// Returns an error if ingestion storage cannot be read.
    pub async fn latest_ingestion(
        root: &Path,
    ) -> Result<Option<(PathBuf, IngestionKey)>, EntitySearchPipelineError> {
        let root = path::absolute(root).map_err(|e| read_error(root, e))?;
        let mut entries = match fs::read_dir(&root).await {
            Ok(entries) => entries,
            Err(error) if error.kind() == ErrorKind::NotFound => return Ok(None),
            Err(error) => return Err(read_error(&root, error)),
        };
        let mut latest: Option<(SystemTime, PathBuf, IngestionKey)> = None;
        while let Some(entry) = entries
            .next_entry()
            .await
            .map_err(|e| read_error(&root, e))?
        {
            let path = entry.path();
            if !entry
                .file_type()
                .await
                .map_err(|e| read_error(&path, e))?
                .is_dir()
            {
                continue;
            }
            let Some(key) = entry
                .file_name()
                .to_str()
                .and_then(|name| name.parse::<IngestionKey>().ok())
            else {
                continue;
            };
            let modified_at = entry
                .metadata()
                .await
                .and_then(|metadata| metadata.modified())
                .map_err(|e| read_error(&path, e))?;
            if latest.as_ref().is_none_or(|(latest_time, _, latest_key)| {
                (modified_at, key.uuid()) > (*latest_time, latest_key.uuid())
            }) {
                latest = Some((modified_at, path, key));
            }
        }
        Ok(latest.map(|(_, path, key)| (path, key)))
    }

    /// Copies the latest run's entire raw layer into a new ingestion run.
    /// Returns the published destination run path and the selected source key.
    /// An absent or empty store returns `None` without creating directories.
    ///
    /// # Errors
    /// Returns an error for unreadable raw data, symlinks, special files, or an
    /// existing destination. Failed copies leave no published run.
    pub async fn copy_latest_raw(
        root: &Path,
        key: IngestionKey,
    ) -> Result<Option<(PathBuf, IngestionKey)>, EntitySearchPipelineError> {
        let root = path::absolute(root).map_err(|error| read_error(root, error))?;
        let Some((source, source_key)) = Self::latest_ingestion(&root).await? else {
            return Ok(None);
        };
        let destination = root.join(key.to_string());
        let staging = tempfile::Builder::new()
            .prefix(".raw-copy-")
            .tempdir_in(&root)
            .map_err(|error| write_error(&root, error))?;
        copy_raw_directory(&source.join("raw"), &staging.path().join("raw")).await?;
        publish_directory(staging.path(), &destination)
            .map_err(|error| write_error(&destination, error))?;
        Ok(Some((destination, source_key)))
    }

    /// Creates a new instance of [`ExposedDataPipeline`] with an [`IngestionKey`]
    ///
    /// # Errors
    /// - if [`root`] cannot be parsed as absolute
    /// - if required directories cannot be created
use clap::Parser;
use exposed::inbound::{
    cli::{Commands, ExposedCli, IntoResponse, Response, run_cli, run_migrate},
    http::server::run_server,
};

fn main() -> anyhow::Result<std::process::ExitCode> {
    let args = ExposedCli::parse();
    match args.command {
        Commands::Server => run_server().map(|()| std::process::ExitCode::SUCCESS),
        Commands::Migrate(args) => {
            dotenvy::dotenv().ok();
            let response = match tokio::runtime::Runtime::new() {
                Ok(runtime) => runtime.block_on(run_migrate(args)),
                Err(error) => Err::<Response, _>(error).into_response(),
            };
            Ok(response.write_to(std::io::stdout().lock(), std::io::stderr().lock())?)
        }
        Commands::Data(args) => {
            dotenvy::dotenv().ok();
            let response = match tokio::runtime::Runtime::new() {
                Ok(runtime) => runtime.block_on(run_cli(args)),
                Err(error) => Err::<Response, _>(error).into_response(),
            };
            Ok(response.write_to(std::io::stdout().lock(), std::io::stderr().lock())?)
        }
    }
}
