enum MigrateCommand {
    /// Apply pending up migrations.
    #[command(after_long_help = response_help::single(run))]
    Run {
        /// Migration directory, relative to the current working directory.
        #[arg(long, default_value = "db/migrations")]
        source: PathBuf,
    },
